import React, { useContext, useState } from "react";
import "./GoalsAndPortfolios.scss";
import { goalsAndPortfolios } from "../../portfolio";
import { Fade } from "react-reveal";
import StyleContext from "../../contexts/StyleContext";

export default function GoalsAndPortfolios() {
  const { isDark } = useContext(StyleContext);
  const [activeTab, setActiveTab] = useState(goalsAndPortfolios.categories[0].id);

  if (!goalsAndPortfolios.display) {
    return null;
  }

  const activeCategory = goalsAndPortfolios.categories.find(c => c.id === activeTab);

  return (
    <div className="main" id="goals">
      <Fade bottom duration={1000} distance="20px">
        <h1 className="skills-heading">{goalsAndPortfolios.title}</h1>
        <p className={isDark ? "dark-mode subTitle" : "subTitle"}>
          {goalsAndPortfolios.subtitle}
        </p>

        <div className="goals-tabs">
          {goalsAndPortfolios.categories.map((category) => (
            <button
              key={category.id}
              className={`goals-tab-button ${activeTab === category.id ? "active" : ""} ${isDark ? "dark" : ""}`}
              onClick={() => setActiveTab(category.id)}
            >
              {category.name}
            </button>
          ))}
        </div>

        <div className="goals-content">
          <Fade bottom duration={500} distance="10px" key={activeTab}>
            <div className="projects-container">
              {activeCategory.items.map((item, i) => (
                <div
                  key={i}
                  className={
                    isDark
                      ? "dark-mode project-card project-card-dark"
                      : "project-card project-card-light"
                  }
                >
                  {item.pdf ? (
                    <div className="project-image" style={{ height: "250px" }}>
                      <iframe
                        src={process.env.PUBLIC_URL + item.pdf.substring(1)}
                        title={item.title}
                        style={{ width: "100%", height: "100%", border: "none" }}
                      />
                    </div>
                  ) : item.image ? (
                    <div className="project-image">
                      <img
                        src={item.image}
                        alt={item.title}
                        className="card-image"
                      />
                    </div>
                  ) : null}
                  <div className="project-detail">
                    <h5 className={isDark ? "dark-mode card-title" : "card-title"}>
                      {item.title}
                    </h5>
                    <p className={isDark ? "dark-mode card-subtitle" : "card-subtitle"}>
                      {item.desc}
                    </p>
                  </div>
                </div>
              ))}
            </div>
          </Fade>
        </div>
      </Fade>
    </div>
  );
}
