import React, { useContext } from "react";
import "./CourseProjects.scss";
import { courseProjects } from "../../portfolio";
import { Fade } from "react-reveal";
import StyleContext from "../../contexts/StyleContext";

export default function CourseProjects() {
  const { isDark } = useContext(StyleContext);

  if (!courseProjects.display) {
    return null;
  }

  return (
    <div className="main" id="course-projects">
      <Fade bottom duration={1000} distance="20px">
        <h1 className="skills-heading">{courseProjects.title}</h1>
        <p className={isDark ? "dark-mode subTitle" : "subTitle"}>
          {courseProjects.subtitle}
        </p>

        <div className="projects-container course-projects-container">
          {courseProjects.projects.map((project, i) => (
            <div
              key={i}
              className={
                isDark
                  ? "dark-mode project-card project-card-dark course-card"
                  : "project-card project-card-light course-card"
              }
            >
              {project.pdf ? (
                <div className="project-image course-image-wrapper">
                  <iframe
                    src={process.env.PUBLIC_URL + project.pdf.substring(1)}
                    title={project.title}
                    className="card-image course-image"
                    style={{ border: "none" }}
                  />
                </div>
              ) : project.image ? (
                <div className="project-image course-image-wrapper">
                  <img
                    src={project.image}
                    alt={project.title}
                    className="card-image course-image"
                  />
                </div>
              ) : null}
              <div className="project-detail">
                <span className={isDark ? "dark-mode course-category" : "course-category"}>
                  {project.category}
                </span>
                <h5 className={isDark ? "dark-mode card-title" : "card-title"}>
                  {project.title}
                </h5>
                <p className={isDark ? "dark-mode card-subtitle" : "card-subtitle"}>
                  {project.desc}
                </p>
              </div>
            </div>
          ))}
        </div>
      </Fade>
    </div>
  );
}
