import React, {useContext} from "react";
import "./AboutMe.scss";
import {aboutMe} from "../../portfolio";
import {Fade} from "react-reveal";
import StyleContext from "../../contexts/StyleContext";

export default function AboutMe() {
  const {isDark} = useContext(StyleContext);

  if (!aboutMe.display) {
    return null;
  }

  return (
    <Fade bottom duration={1000} distance="20px">
      <div className={isDark ? "dark-mode main" : "main"} id="about">
        <div className="about-main-div">
          <div className="about-header">
            <h1 className={isDark ? "dark-mode about-heading" : "about-heading"}>
              {aboutMe.title}
            </h1>
            <p className={isDark ? "dark-mode subTitle about-subtitle" : "subTitle about-subtitle"}>
              {aboutMe.subtitle}
            </p>
          </div>

          <div className="about-content-div">
            {/* Bio paragraphs */}
            <div className="about-bio-div">
              {aboutMe.paragraphs.map((para, i) => (
                <p
                  key={i}
                  className={isDark ? "dark-mode about-bio-text" : "about-bio-text"}
                >
                  {para}
                </p>
              ))}
            </div>

            {/* Key Events Timeline */}
            <div className="about-timeline-div">
              <h2 className={isDark ? "dark-mode about-timeline-heading" : "about-timeline-heading"}>
                Key Milestones
              </h2>
              <div className="timeline">
                {aboutMe.keyEvents.map((event, i) => (
                  <div key={i} className={`timeline-item ${i % 2 === 0 ? "left" : "right"}`}>
                    <div className={isDark ? "dark-mode timeline-content" : "timeline-content"}>
                      <h3 className={isDark ? "dark-mode timeline-title" : "timeline-title"}>{event.event}</h3>
                      <p className={isDark ? "dark-mode timeline-insight" : "timeline-insight"}>{event.insight}</p>
                    </div>
                  </div>
                ))}
              </div>
            </div>
          </div>
        </div>
      </div>
    </Fade>
  );
}
